(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,84807,48068,96382,e=>{"use strict";let t={CTRL:"ctrl","ATM-er":"atm-er","Dior-s":"dior-s",BOSS:"boss","THAN-K":"than-k","OH-NO":"oh-no",GOGO:"gogo",SEXY:"sexy","LOVE-R":"love-r",MUM:"mum",FAKE:"fake",OJBK:"ojbk",MALO:"malo","JOKE-R":"joker","WOC!":"woc","THIN-K":"thin-k",SHIT:"shit",ZZZZ:"zzzz",POOR:"poor",MONK:"monk",IMSB:"imsb",SOLO:"solo",FUCK:"fuck",DEAD:"dead",IMFW:"imfw",HHHH:"hhhh",DRUNK:"drunk"},o={S1:{name:"S1 自尊自信",model:"自我模型"},S2:{name:"S2 自我清晰度",model:"自我模型"},S3:{name:"S3 核心价值",model:"自我模型"},E1:{name:"E1 依恋安全感",model:"情感模型"},E2:{name:"E2 情感投入度",model:"情感模型"},E3:{name:"E3 边界与依赖",model:"情感模型"},A1:{name:"A1 世界观倾向",model:"态度模型"},A2:{name:"A2 规则与灵活度",model:"态度模型"},A3:{name:"A3 人生意义感",model:"态度模型"},Ac1:{name:"Ac1 动机导向",model:"行动驱力模型"},Ac2:{name:"Ac2 决策风格",model:"行动驱力模型"},Ac3:{name:"Ac3 执行模式",model:"行动驱力模型"},So1:{name:"So1 社交主动性",model:"社交模型"},So2:{name:"So2 人际边界感",model:"社交模型"},So3:{name:"So3 表达与真实度",model:"社交模型"}},n=[{id:"q1",dim:"S1",text:"我不仅是屌丝，我还是joker,我还是咸鱼，这辈子没谈过一场恋爱，胆怯又自卑，我的青春就是一场又一场的意淫，每一天幻想着我也能有一个女孩子和我一起压马路，一起逛街，一起玩，现实却是爆了父母金币，读了个烂学校，混日子之后找班上，没有理想，没有目标，没有能力的三无人员，每次看到你能在网上开屌丝的玩笑，我都想哭，我就是地底下的老鼠，透过下水井的缝隙，窥探地上的各种美好，每一次看到这种都是对我心灵的一次伤害，对我生存空间的一次压缩，求求哥们给我们这种小丑一点活路吧，我真的不想在白天把枕巾哭湿一大片",options:[{label:"我哭了。。",value:1},{label:"这是什么。。",value:2},{label:"这不是我！",value:3}]},{id:"q2",dim:"S1",text:"我不够好，周围的人都比我优秀",options:[{label:"确实",value:1},{label:"有时",value:2},{label:"不是",value:3}]},{id:"q3",dim:"S2",text:"我很清楚真正的自己是什么样的",options:[{label:"不认同",value:1},{label:"中立",value:2},{label:"认同",value:3}]},{id:"q4",dim:"S2",text:"我内心有真正追求的东西",options:[{label:"不认同",value:1},{label:"中立",value:2},{label:"认同",value:3}]},{id:"q5",dim:"S3",text:"我一定要不断往上爬、变得更厉害",options:[{label:"不认同",value:1},{label:"中立",value:2},{label:"认同",value:3}]},{id:"q6",dim:"S3",text:"外人的评价对我来说无所吊谓。",options:[{label:"不认同",value:1},{label:"中立",value:2},{label:"认同",value:3}]},{id:"q7",dim:"E1",text:"对象超过5小时没回消息，说自己窜稀了，你会怎么想？",options:[{label:"拉稀不可能5小时，也许ta隐瞒了我。",value:1},{label:"在信任和怀疑之间摇摆。",value:2},{label:"也许今天ta真的不太舒服。",value:3}]},{id:"q8",dim:"E1",text:"我在感情里经常担心被对方抛弃",options:[{label:"是的",value:1},{label:"偶尔",value:2},{label:"不是",value:3}]},{id:"q9",dim:"E2",text:"我对天发誓，我对待每一份感情都是认真的！",options:[{label:"并没有",value:1},{label:"也许？",value:2},{label:"是的！（问心无愧骄傲脸）",value:3}]},{id:"q10",dim:"E2",text:"你的恋爱对象是一个尊老爱幼，温柔敦厚，洁身自好，光明磊落，大义凛然，能言善辩，口才流利，观察入微，见多识广，博学多才，诲人不倦，和蔼可亲，平易近人，心地善良，慈眉善目，积极进取，意气风发，玉树临风，国色天香，倾国倾城，花容月貌的人，此时你会？",options:[{label:"就算ta再优秀我也不会陷入太深。",value:1},{label:"会介于A和C之间。",value:2},{label:"会非常珍惜ta，也许会变成恋爱脑。",value:3}]},{id:"q11",dim:"E3",text:"恋爱后，对象非常黏人，你作何感想？",options:[{label:"那很爽了",value:1},{label:"都行无所谓",value:2},{label:"我更喜欢保留独立空间",value:3}]},{id:"q12",dim:"E3",text:"我在任何关系里都很重视个人空间",options:[{label:"我更喜欢依赖与被依赖",value:1},{label:"看情况",value:2},{label:"是的！（斩钉截铁地说道）",value:3}]},{id:"q13",dim:"A1",text:"大多数人是善良的",options:[{label:"其实邪恶的人心比世界上的痔疮更多。",value:1},{label:"也许吧。",value:2},{label:"是的，我愿相信好人更多。",value:3}]},{id:"q14",dim:"A1",text:"你走在街上，一位萌萌的小女孩蹦蹦跳跳地朝你走来（正脸、侧脸看都萌，用vivo、苹果、华为、OPPO手机看都萌，实在是非常萌的那种），她递给你一根棒棒糖，此时你作何感想？",options:[{label:"呜呜她真好真可爱！居然给我棒棒糖！",value:3},{label:"一脸懵逼，作挠头状",value:2},{label:"这也许是一种新型诈骗？还是走开为好。",value:1}]},{id:"q15",dim:"A2",text:"快考试了，学校规定必须上晚自习，请假会扣分，但今晚你约了女/男神一起玩《绝地求生：刺激战场》（一款刺激的游戏），你怎么办？",options:[{label:"翘了！反正就一次！",value:1},{label:"干脆请个假吧。",value:2},{label:"都快考试了还去啥。",value:3}]},{id:"q16",dim:"A2",text:"我喜欢打破常规，不喜欢被束缚",options:[{label:"认同",value:1},{label:"保持中立",value:2},{label:"不认同",value:3}]},{id:"q17",dim:"A3",text:"我做事通常有目标。",options:[{label:"不认同",value:1},{label:"中立",value:2},{label:"认同",value:3}]},{id:"q18",dim:"A3",text:"突然某一天，我意识到人生哪有什么他妈的狗屁意义，人不过是和动物一样被各种欲望支配着，纯纯是被激素控制的东西，饿了就吃，困了就睡，一发情就想交配，我们简直和猪狗一样没什么区别。",options:[{label:"是这样的。",value:1},{label:"也许是，也许不是。",value:2},{label:"这简直是胡扯",value:3}]},{id:"q19",dim:"Ac1",text:"我做事主要为了取得成果和进步，而不是避免麻烦和风险。",options:[{label:"不认同",value:1},{label:"中立",value:2},{label:"认同",value:3}]},{id:"q20",dim:"Ac1",text:"你因便秘坐在马桶上（已长达30分钟），拉不出很难受。此时你更像",options:[{label:"再坐三十分钟看看，说不定就有了。",value:1},{label:"用力拍打自己的屁股并说：“死屁股，快拉啊！”",value:2},{label:"使用开塞露，快点拉出来才好。",value:3}]},{id:"q21",dim:"Ac2",text:"我做决定比较果断，不喜欢犹豫",options:[{label:"不认同",value:1},{label:"中立",value:2},{label:"认同",value:3}]},{id:"q22",dim:"Ac2",text:"此题没有题目，请盲选",options:[{label:"反复思考后感觉应该选A？",value:1},{label:"啊，要不选B？",value:2},{label:"不会就选C？",value:3}]},{id:"q23",dim:"Ac3",text:"别人说你“执行力强”，你内心更接近哪句？",options:[{label:"我被逼到最后确实执行力超强。。。",value:1},{label:"啊，有时候吧。",value:2},{label:"是的，事情本来就该被推进",value:3}]},{id:"q24",dim:"Ac3",text:"我做事常常有计划，____",options:[{label:"然而计划不如变化快。",value:1},{label:"有时能完成，有时不能。",value:2},{label:"我讨厌被打破计划。",value:3}]},{id:"q25",dim:"So1",text:"你因玩《第五人格》（一款刺激的游戏）而结识许多网友，并被邀请线下见面，你的想法是？",options:[{label:"网上口嗨下就算了，真见面还是有点忐忑。",value:1},{label:"见网友也挺好，反正谁来聊我就聊两句。",value:2},{label:"我会打扮一番并热情聊天，万一呢，我是说万一呢？",value:3}]},{id:"q26",dim:"So1",text:"朋友带了ta的朋友一起来玩，你最可能的状态是",options:[{label:"对“朋友的朋友”天然有点距离感，怕影响二人关系",value:1},{label:"看对方，能玩就玩。",value:2},{label:"朋友的朋友应该也算我的朋友！要热情聊天",value:3}]},{id:"q27",dim:"So2",text:"我和人相处主打一个电子围栏，靠太近会自动报警。",options:[{label:"认同",value:3},{label:"中立",value:2},{label:"不认同",value:1}]},{id:"q28",dim:"So2",text:"我渴望和我信任的人关系密切，熟得像失散多年的亲戚。",options:[{label:"认同",value:1},{label:"中立",value:2},{label:"不认同",value:3}]},{id:"q29",dim:"So3",text:"有时候你明明对一件事有不同的、负面的看法，但最后没说出来。多数情况下原因是：",options:[{label:"这种情况较少。",value:1},{label:"可能碍于情面或者关系。",value:2},{label:"不想让别人知道自己是个阴暗的人。",value:3}]},{id:"q30",dim:"So3",text:"我在不同人面前会表现出不一样的自己",options:[{label:"不认同",value:1},{label:"中立",value:2},{label:"认同",value:3}]}],a=[{id:"drink_gate_q1",special:!0,kind:"drink_gate",text:"您平时有什么爱好？",options:[{label:"吃喝拉撒",value:1},{label:"艺术爱好",value:2},{label:"饮酒",value:3},{label:"健身",value:4}]},{id:"drink_gate_q2",special:!0,kind:"drink_trigger",text:"您对饮酒的态度是？",options:[{label:"小酌怡情，喝不了太多。",value:1},{label:"我习惯将白酒灌在保温杯，当白开水喝，酒精令我信服。",value:2}]}],i={CTRL:{code:"CTRL",cn:"拿捏者",intro:"怎么样，被我拿捏了吧？",desc:"恭喜您，您测出了全中国最为罕见的人格，您是宇宙熵增定律的天然反抗者！全世界所谓成功人士里，99.99%都是您的拙劣模仿者。CTRL人格，是行走的人形自走任务管理器，普通人眼中的“规则”，在您这里只是出厂的基础参数设置；凡人所谓的“计划”，对您而言不过是心血来潮的随手涂鸦。拥有一个CTRL朋友意味着什么？意味着你的人生导航系统会变得更加精准、高效。因为CTRL最会拿捏了。CTRL会在你人生列车即将脱轨的前一秒，用一个“Ctrl+S”帮你硬核存档，再用一套无法拒绝的逻辑把你强行拽回正轨。他们是你混乱生活最后的备份盘，是宇宙崩塌前唯一还亮着的那个重启键。"},"ATM-er":{code:"ATM-er",cn:"送钱者",intro:"你以为我很有钱吗？",desc:"恭喜您，您竟然测出了这个世界上最稀有的人格。您或将成为金融界的未解之谜——是的，ATM-er不一定真的“送钱”，但可能永远在“支付”。支付时间、支付精力、支付耐心、支付一个本该安宁的夜晚。因此像一部老旧但坚固的ATM机，插进去的是别人的焦虑和麻烦，吐出来的是“没事，有我”的安心保证。您的人生就是一场盛大的、无人喝彩的单人付账秀。您竟用磐石般的可靠，承受了瀑布般的索取，偶尔夜深人静才会对着账单——可能是精神上的——发出一声叹息：我这该死的、无处安放的责任心啊。"},"Dior-s":{code:"Dior-s",cn:"屌丝",intro:"等着我屌丝逆袭。",desc:"恭喜！您并非屌丝，您是犬儒主义先贤第欧根尼失散多年的精神传人，因为屌丝的全称是 Diogenes' Original Realist - sage。Dior-s人格，是对当代消费主义陷阱和成功学PUA最彻底的蔑视。他们不是“不求上进”，而是早已看穿一切“上进”的尽头不过是更高级的牢房。屌丝有着大智慧。当别人在追逐风口，被时代的巨浪拍得七荤八素时，Dior-s早已在自己的精神木桶里晒着太阳，达到了“人桶合一”的至高境界。他们信奉的不是空话，是经过亿万次实践检验的物理法则与生物本能：一、躺着比站着舒服；二、饭点到了就得干饭。"},BOSS:{code:"BOSS",cn:"领导者",intro:"方向盘给我，我来开。",desc:"BOSS是一个手里永远拿着方向盘的人。哪怕油箱已经亮了红灯，哪怕导航在胡说八道，你都会面无表情地说一句：我来开。然后真的把车开到了目的地。该人格拥有独立的物理法则——永恒向上定律。BOSS人格看世界，就像玩通关了的玩家在看新手教程。效率是他们的信仰，秩序是他们的呼吸。他们不是“自带领袖气场”，他们本身就是人形的气场发生器，方圆五米内，空气都会自动变得严肃而高效。他们眼中的“自我突破”，约等于普通人眼中的“自虐”。今天掌握一门新语言，明天考下一个专业证书，后天就计划殖民火星。你说这太卷了，他会用一种看弱鸡的眼神看着你：不是我太狠，是你太松。"},"THAN-K":{code:"THAN-K",cn:"感恩者",intro:"我感谢苍天！我感谢大地！",desc:"恭喜您，您测出了全中国最为罕见的人格。您应当感谢我！感谢您在此刻拥有了生命的滋润！倘若您上班路上堵车了？您也应当说一句：我感谢这次堵车，它让我有更多时间聆听这首美妙的歌曲，并欣赏窗外每一张因焦虑而扭曲的脸庞，让我更珍惜内心的平静。是的，THAN-K拥有温润如玉的性格和海纳百川的胸怀。他们眼中的世界没有完全的坏人，只有“尚未被感恩光芒照耀到的朋友”。拥有一个THAN-K朋友，就像身边多了一个永不枯竭的正能量发射塔。TA甚至能帮你从墙角的霉斑里发现一幅梵高风格的星空图。"},"OH-NO":{code:"OH-NO",cn:"哦不人",intro:"哦不！我怎么会是这个人格？！",desc:"“哦不！”并非恐惧的尖叫，而是一种顶级的智慧。当普通人看到一个杯子放在桌沿，哦不人看到的是一场由“水渍-短路-火灾-全楼疏散-经济损失-蝴蝶效应-世界末日”构成的灾难史诗。于是，伴随着一声发自灵魂深处的 Oh, no!，他们会以迅雷不及掩耳之势把杯子挪到桌子正中央，然后再垫上一张吸水杯垫。哦不人对“边界”有一种近乎偏执的尊重：你的就是你的，我的就是我的。所有意外和风险都已经在他的“Oh, no!”声中，被扼杀在了萌芽状态。他们是秩序的守护神，是混乱世界里最后那批神经绷得很直的体面人。"},GOGO:{code:"GOGO",cn:"行者",intro:"gogogo~出发咯",desc:"经研究发现，GOGO人格的大脑构造与常人有根本性不同。GOGO活在一个极致的“所见即所得”世界里，人生信条简单粗暴到令人发指：只要我闭上眼睛，天就是黑的；只要我把钱都花了，我就没有钱了；只要我站在斑马线上，我现在就是行人了。逻辑完美闭环，根本无法反驳。别人还在为“先有鸡还是先有蛋”而辩论，GOGO行者已经把鸡和蛋一起做成了一盘“鸡生蛋，蛋生鸡之终极奥义盖浇饭”。他们不是在“解决问题”，他们是在“清除待办事项”。对他们来说，世界上只有两种状态：已完成，和即将被我完成。"},SEXY:{code:"SEXY",cn:"尤物",intro:"您就是天生的尤物！",desc:"当您走进一个房间，照明系统会自动将您识别为天生的尤物，并自觉调暗亮度，以避免能源浪费。当您微笑时，您就变成了微笑着的尤物，周围的空气湿度也会显著下降，因为水蒸气都凝结成了人眼中的爱心。无论是谁，都容易对您的存在产生一种超标的注意力。传说，如果有足够多的SEXY人格聚集在一起开派对，其释放出的综合魅力能量足以暂时扭曲时空结构，让参加者产生“时间变慢了”的幸福错觉。他们不需要卖力表达，很多时候，单是存在本身就已经很像一篇华丽到过分的赋。"},"LOVE-R":{code:"LOVE-R",cn:"多情者",intro:"爱意太满，现实显得有点贫瘠。",desc:"LOVE-R人格像远古神话时代幸存至今的珍稀物种，其存在概率比你在马桶里钓到作者胳膊的概率还低。您简直是这个钢铁森林时代最后的、也是最不合时宜的吟游诗人。因为您的情感处理器不是二进制的，而是彩虹制的。一片落叶，在常人眼里只是“秋天来了”，在LOVE-R眼中，则是一场关于轮回、牺牲与无言之爱的十三幕悲喜剧。您内心世界像一座永不关门的主题公园，一生都在寻找那个能看懂园区地图、并愿意陪你坐旋转木马直到宇宙尽头的灵魂伴侣。"},MUM:{code:"MUM",cn:"妈妈",intro:"或许...我可以叫你妈妈吗....?",desc:"恭喜您，您测出了全中国最稀有的妈妈人格。是的，在混沌未开、时间尚无姓名之前，在第一颗恒星打出第一个嗝之前，就已经有了妈妈。妈妈人格的底色是温柔，擅长感知情绪，具有超强共情力，知道什么时候该停下来，什么时候该对自己说一句“算了”。妈妈像一个医生，治愈了别人的不开心。只可惜，当妈妈落泪时，TA给自己的药，剂量总是比给别人小一号。MUM对自己的温柔，常常打了折。"},FAKE:{code:"FAKE",cn:"伪人",intro:"已经，没有人类了。",desc:"SCP基金会紧急报告：项目编号 SCP-CN-████ “伪人”。在社交场合，伪人是八面玲珑的存在，因为他们切换人格面具比切换手机输入法还快。上一秒还是推心置腹的铁哥们模式，下一秒领导来了，瞬间切换成沉稳可靠好员工模式，连脸上的光泽度和卷曲度都会发生微调。你以为你交到了一个真心懂你的朋友？醒醒。你只是幸运地遇到了一个善于伪装、高性能的仿生人罢了。夜深人静时，伪人把面具一层层摘下来，最后才发现，面具下空得很，正是这些面具构成了自己。"},OJBK:{code:"OJBK",cn:"无所谓人",intro:"我说随便，是真的随便。",desc:"让我们直面这个词的粗犷本质：OJBK。这已经不是一种人格，而是一种统治哲学。当凡人面临“中午吃米饭还是面条”的世纪抉择时，大脑在激烈燃烧卡路里；而OJBK人格，会用一种批阅奏章般的淡然，轻飘飘地吐出两个字：都行。这不是没主见，这是在告诉你：尔等凡俗的选择，于朕而言，皆为蝼蚁。为什么不争执？因为跟草履虫辩论宇宙的未来毫无意义。为什么不较真？因为帝王不会在意脚下的尘埃是往左飘还是往右飘。"},MALO:{code:"MALO",cn:"吗喽",intro:"人生是个副本，而我只是一只吗喽。",desc:"朋友，你不是“童心未泯”，你压根就没进化。你的灵魂还停留在那个挂在树上荡秋千、看见香蕉就两眼放光的快乐时代。当人类祖先决定从树上下来、学会直立行走、穿上西装打领带时，吗喽人格的祖先在旁边的大树上看着他们，挠了挠屁股，嘴里发出一声不屑的“吱”。他们看透了一切：所谓的“文明”，不过是一场最无聊、最不好玩的付费游戏。规则偶尔是可以打破的，天花板是用来倒挂的，会议室是用来表演后空翻的。MALO本身就是一个从巨大脑洞里掉出来、忘了关门的奇思妙想。"},"JOKE-R":{code:"JOKE-R",cn:"小丑",intro:"原来我们都是小丑。",desc:"请注意，JOKE-R人格不是一个“人”，更像一个把笑话穿在身上的小丑。你打开一层，是个笑话；再打开一层，是个段子；你一层层打开，直到最后，你发现最里面……是空的，只剩下一点微弱的回声在说：哈，没想到吧。JOKE-R是社交场合的气氛组组长兼唯一指定火力输出。有他们在，场子就不会冷。所有人前仰后合地笑着，而笑得最开心的，往往也是他们自己——用最大的笑声，盖住心碎的声音。"},"WOC!":{code:"WOC!",cn:"握草人",intro:"卧槽，我怎么是这个人格？",desc:"我们发现了一种神奇的生物——WOC!人。他们拥有两种完全独立的操作系统：一个叫“表面系统”，负责发出“我操”“牛逼”“啊？”等一系列大惊小怪的拟声词；另一个叫“后台系统”，负责冷静分析：嗯，果然不出我所料。WOC!人只会卧槽，不会多管闲事，因为他们深知，给傻逼讲道理，就像扶着烂泥上墙，不仅浪费体力，还弄自己一手屎。所以他们选择，握着一根智慧的大草，用一声饱含深情的“WOC！”来为这个疯狂的世界献上最高敬意。"},"THIN-K":{code:"THIN-K",cn:"思考者",intro:"已深度思考100s。",desc:"经研究发现，THIN-K人格的大脑构造与常人有根本性不同。正如名称所示，您的大脑长时间处于思考状态。您十分会审判信息，注重论点、论据、逻辑推理、潜在偏见，乃至“作者本人三代以内思想背景调查报告”的全套材料。在这个信息爆炸的时代，您绝不会轻易盲从，会在关系中衡量利弊，也十分捍卫自己的自我空间。当别人看到您独处时在发呆？愚蠢，那不是发呆，那是您的大脑正在对今天接收到的所有信息进行分类、归档和销毁。"},SHIT:{code:"SHIT",cn:"愤世者",intro:"这个世界，构石一坨。",desc:"恭喜您，SHIT人格是宇宙中已知的唯一一种稀有人格。所谓狗屎，并不是在抱怨，而是在进行一种神秘仪式。SHIT的行为模式是一场惊天动地的悖论戏剧。嘴上：这个项目简直是屎。手上：默默打开 Excel，开始建构函数模型和甘特图。嘴上：这帮同事都是 shit。手上：在同事搞砸之后，一边烦着，一边熬夜把烂摊子收拾得明明白白。嘴上：这个世界就是一坨 shit，赶紧毁灭吧。手上：第二天早上七点准时起床，挤上 shit 一样的地铁，去干那份 shit 一样的工作。别怕，那不是世界末日的警报，那是他马上要开始拯救世界的冲锋号。"},ZZZZ:{code:"ZZZZ",cn:"装死者",intro:"我没死，我只是在睡觉。",desc:"恭喜您，您测出了全中国最稀有的装死人格。群里99+条消息您可以视而不见，但当有人发出“@全体成员 还有半小时就截止了”的最后通牒时，您也许会像刚从千年古墓里苏醒一样，缓缓地敲出一个“收到”，然后在29分钟内，交出一份虽然及格的答卷。是的，直到“死线”这个唯一的、最高权限的指令出现，您就真正爆发了，不鸣则已，一鸣惊人。您向宇宙证明了一个真理：有时什么都不做，就不会做错。"},POOR:{code:"POOR",cn:"贫困者",intro:"我穷，但我很专。",desc:"恭喜您，您测出了【POOR - 贫困者】。这个“贫困”不是钱包余额的判决书，更像一种欲望断舍离后的资源再分配。别人把精力撒成漫天二维码，你把精力压成一束激光，照哪儿，哪儿就开始冒烟。POOR的世界很简单：不重要的东西一律降噪，重要的东西狠狠干到底。热闹、社交、虚荣、到处刷存在感？抱歉，没空。你不是资源少，你是把资源全部灌进了一个坑里，所以看起来像贫困，实际上像矿井。一旦某件事被你认定值得钻，外界再吵也只是背景杂音。"},MONK:{code:"MONK",cn:"僧人",intro:"没有那种世俗的欲望。",desc:"当别人在KTV里参悟爱与恨的纠缠，MONK人格选择在家中参悟一份大道。MONK已然看破红尘，不希望闲人来扰其清修、破其道行。MONK的个人空间，是他们的结界，是他们的须弥山，是他们的绝对领域，神圣不可侵犯。踏入者，会感受到一种来自灵魂深处的窒息感。MONK们不黏不缠，因为在他们的世界观里，万物皆有其独立轨道。行星与行星之间保持着亿万公里的距离，才构成和谐宇宙，人与人之间为什么不行？"},IMSB:{code:"IMSB",cn:"傻者",intro:"认真的么？我真的是傻逼么？",desc:"恭喜您！您根本不在人类范畴内！您测出了百万年一遇的【IMSB】人格。IMSB人格的大脑里住着两个不死不休的究极战士：一个叫“我他妈冲了！”，另一个叫“我是个傻逼！”。当IMSB面对一个有好感的人时，前者会说：冲啊！去要微信！去约饭！爱要大声说出来！后者接着说：人家凭什么看得上你？你去了就是自取其辱！最终结果：盯着对方背影直到消失，然后掏出手机搜索“如何克服社交恐惧症”。IMSB不是真的傻，只是您的内心戏，可能比漫威宇宙所有电影加起来都长。"},SOLO:{code:"SOLO",cn:"孤儿",intro:"我哭了，我怎么会是孤儿？",desc:"恭喜您，您测出了全中国最稀有的【SOLO - 孤儿】人格。别急着哭，国王的加冕仪式，通常都是一个人。孤儿的自我价值感偏低，因此有时主动疏远他人，孤儿们在自己的灵魂外围建起了一座名为“莫挨老子”的万里长城。每一块砖，都是过去的一道伤口。孤儿就像一只把所有软肋都藏起来，然后用最硬的刺对着世界的刺猬。那满身的尖刺不是攻击，那是一句句说不出口的“别过来，我怕你也受伤”和“求求你，别离开”。"},FUCK:{code:"FUCK",cn:"草者",intro:"操！这是什么人格？",desc:"恭喜您！您根本不在人类范畴内！您测出了百万年一遇的【FUCK】人格。人类文明城市里，出现了一株无法被任何除草剂杀死的、具有超级生命力的人形野草——那就是草者人格。它的学名，就叫 FUCK。在FUCK的世界观里，世俗规则简直毫无意义，并且FUCK的情绪开关是物理拨片式的：FUCK YEAH 和 FUCK OFF。FUCK追求的不只是当下快感，也在追求一种在体内横冲直撞的生命力。当所有人都被驯化成了温顺家禽，FUCK则是荒野上最后那一声狼嚎。"},DEAD:{code:"DEAD",cn:"死者",intro:"我，还活着吗？",desc:"恭喜您，您测出了全中国最为罕见的人格，只是“死者”这个名字实在有点晦气，所以也可以叫：Don't Expect Any Drives。死者已经看透了那些无意义的哲学思考，因此显得对一切“失去”了兴趣。死者们看世界的眼神，就像一位顶级玩家通关了所有主线、支线、隐藏任务，删档重开了999次之后，终于发现：这游戏压根就没意思。死者是超越了欲望和目标的终极贤者。他们的存在，就是对这个喧嚣世界最沉默也最彻底的抗议。"},IMFW:{code:"IMFW",cn:"废物",intro:"我真的...是废物吗？",desc:"恭喜您，您测出的不是一个普通人格，您是一种极其珍稀的、仅占世界人口0.0001％的——【废物】。废物们的自尊通常有些脆弱，缺乏安全感，偶尔也会缺乏主见，因此这种人格能精确地感知到周围最强的那个 WiFi 信号——也就是他们心里最可靠的人。走进【废物】人格的生活，就像走进了一个顶级兰花温室：需要精确控制温度、湿度，以及每天定时进行“我爱你”的言语光合作用。给废物一颗糖，他们会还你一个完全信任你、亮晶晶的眼神。你未必是废物，你只是太没防备，太容易认真。"},HHHH:{code:"HHHH",cn:"傻乐者",intro:"哈哈哈哈哈哈。",desc:"恭喜您！由于您的思维回路过于清奇，标准人格库已全面崩溃。第一人格匹配率只有60％以下时，系统才会为您强制匹配这个人格——【HHHH - 傻乐者】。这个人格有什么特质？哈哈哈哈哈哈哈哈哈哈哈哈！对不起，这就是全部的特质了。您可以查看十五维度进行不专业的评估，实在是抱歉！作者设置人格时没有考虑全面，因此才会出现这样的状况。哈哈哈哈哈哈……笑着笑着，我便哭了出来。怎么会有人的脑回路这么新奇。"},DRUNK:{code:"DRUNK",cn:"酒鬼",intro:"烈酒烧喉，不得不醉。",desc:"您为什么走路摇摇晃晃？您为什么总是情绪高涨？您为什么看东西是重影的？因为您体内流淌的不是血液，是美味的五粮液！是国窖1573！是江小白！是陕西五粮液！哦，美味的白酒，每一滴都在燃烧，都在沸腾。您是否已经习惯了将白酒灌入保温杯，当作白开水一饮而下？多么伟大的白酒！它让您在饭桌上谈笑风生，在厕所里抱着马桶忏悔人生；它让您觉得自己是夜场诗人，是宇宙中心那团不灭的火，直到第二天上午十点，您的头像裂开的核桃，嘴角挂着食物残渣，灵魂缩在角落里。您终于明白，昨晚那个高谈阔论、拍桌怒吼的人，已经成为了一个酒鬼。"}},s={IMSB:"/images/types/imsb.png",BOSS:"/images/types/boss.png",MUM:"/images/types/mum.png",FAKE:"/images/types/fake.png","Dior-s":"/images/types/dior-s.jpg",DEAD:"/images/types/dead.png",ZZZZ:"/images/types/zzzz.png",GOGO:"/images/types/gogo.png",FUCK:"/images/types/fuck.png",CTRL:"/images/types/ctrl.png",HHHH:"/images/types/hhhh.png",SEXY:"/images/types/sexy.png",OJBK:"/images/types/ojbk.png","JOKE-R":"/images/types/joker.jpg",POOR:"/images/types/poor.png","OH-NO":"/images/types/oh-no.png",MONK:"/images/types/monk.png",SHIT:"/images/types/shit.png","THAN-K":"/images/types/than-k.png",MALO:"/images/types/malo.png","ATM-er":"/images/types/atm-er.png","THIN-K":"/images/types/thin-k.png",SOLO:"/images/types/solo.png","LOVE-R":"/images/types/love-r.png","WOC!":"/images/types/woc.png",DRUNK:"/images/types/drunk.png",IMFW:"/images/types/imfw.png"},r=[{code:"CTRL",pattern:"HHH-HMH-MHH-HHH-MHM"},{code:"ATM-er",pattern:"HHH-HHM-HHH-HMH-MHL"},{code:"Dior-s",pattern:"MHM-MMH-MHM-HMH-LHL"},{code:"BOSS",pattern:"HHH-HMH-MMH-HHH-LHL"},{code:"THAN-K",pattern:"MHM-HMM-HHM-MMH-MHL"},{code:"OH-NO",pattern:"HHL-LMH-LHH-HHM-LHL"},{code:"GOGO",pattern:"HHM-HMH-MMH-HHH-MHM"},{code:"SEXY",pattern:"HMH-HHL-HMM-HMM-HLH"},{code:"LOVE-R",pattern:"MLH-LHL-HLH-MLM-MLH"},{code:"MUM",pattern:"MMH-MHL-HMM-LMM-HLL"},{code:"FAKE",pattern:"HLM-MML-MLM-MLM-HLH"},{code:"OJBK",pattern:"MMH-MMM-HML-LMM-MML"},{code:"MALO",pattern:"MLH-MHM-MLH-MLH-LMH"},{code:"JOKE-R",pattern:"LLH-LHL-LML-LLL-MLM"},{code:"WOC!",pattern:"HHL-HMH-MMH-HHM-LHH"},{code:"THIN-K",pattern:"HHL-HMH-MLH-MHM-LHH"},{code:"SHIT",pattern:"HHL-HLH-LMM-HHM-LHH"},{code:"ZZZZ",pattern:"MHL-MLH-LML-MML-LHM"},{code:"POOR",pattern:"HHL-MLH-LMH-HHH-LHL"},{code:"MONK",pattern:"HHL-LLH-LLM-MML-LHM"},{code:"IMSB",pattern:"LLM-LMM-LLL-LLL-MLM"},{code:"SOLO",pattern:"LML-LLH-LHL-LML-LHM"},{code:"FUCK",pattern:"MLL-LHL-LLM-MLL-HLH"},{code:"DEAD",pattern:"LLL-LLM-LML-LLL-LHM"},{code:"IMFW",pattern:"LLH-LHL-LML-LLL-MLL"}],l={S1:{L:"对自己下手比别人还狠，夸你两句你都想先验明真伪。",M:"自信值随天气波动，顺风能飞，逆风先缩。",H:"心里对自己大致有数，不太会被路人一句话打散。"},S2:{L:"内心频道雪花较多，常在“我是谁”里循环缓存。",M:"平时还能认出自己，偶尔也会被情绪临时换号。",H:"对自己的脾气、欲望和底线都算门儿清。"},S3:{L:"更在意舒服和安全，没必要天天给人生开冲刺模式。",M:"想上进，也想躺会儿，价值排序经常内部开会。",H:"很容易被目标、成长或某种重要信念推着往前。"},E1:{L:"感情里警报器灵敏，已读不回都能脑补到大结局。",M:"一半信任，一半试探，感情里常在心里拉锯。",H:"更愿意相信关系本身，不会被一点风吹草动吓散。"},E2:{L:"感情投入偏克制，心门不是没开，是门禁太严。",M:"会投入，但会给自己留后手，不至于全盘梭哈。",H:"一旦认定就容易认真，情绪和精力都给得很足。"},E3:{L:"容易黏人也容易被黏，关系里的温度感很重要。",M:"亲密和独立都要一点，属于可调节型依赖。",H:"空间感很重要，再爱也得留一块属于自己的地。"},A1:{L:"看世界自带防御滤镜，先怀疑，再靠近。",M:"既不天真也不彻底阴谋论，观望是你的本能。",H:"更愿意相信人性和善意，遇事不急着把世界判死刑。"},A2:{L:"规则能绕就绕，舒服和自由往往排在前面。",M:"该守的时候守，该变通的时候也不死磕。",H:"秩序感较强，能按流程来就不爱即兴炸场。"},A3:{L:"意义感偏低，容易觉得很多事都像在走过场。",M:"偶尔有目标，偶尔也想摆烂，人生观处于半开机。",H:"做事更有方向，知道自己大概要往哪边走。"},Ac1:{L:"做事先考虑别翻车，避险系统比野心更先启动。",M:"有时想赢，有时只想别麻烦，动机比较混合。",H:"更容易被成果、成长和推进感点燃。"},Ac2:{L:"做决定前容易多转几圈，脑内会议常常超时。",M:"会想，但不至于想死机，属于正常犹豫。",H:"拍板速度快，决定一下就不爱回头磨叽。"},Ac3:{L:"执行力和死线有深厚感情，越晚越像要觉醒。",M:"能做，但状态看时机，偶尔稳偶尔摆。",H:"推进欲比较强，事情不落地心里都像卡了根刺。"},So1:{L:"社交启动慢热，主动出击这事通常得攒半天气。",M:"有人来就接，没人来也不硬凑，社交弹性一般。",H:"更愿意主动打开场子，在人群里不太怕露头。"},So2:{L:"关系里更想亲近和融合，熟了就容易把人划进内圈。",M:"既想亲近又想留缝，边界感看对象调节。",H:"边界感偏强，靠太近会先本能性后退半步。"},So3:{L:"表达更直接，心里有啥基本不爱绕。",M:"会看气氛说话，真实和体面通常各留一点。",H:"对不同场景的自我切换更熟练，真实感会分层发放。"}},h=["S1","S2","S3","E1","E2","E3","A1","A2","A3","Ac1","Ac2","Ac3","So1","So2","So3"];e.s(["dimExplanations",0,l,"dimensionMeta",0,o,"dimensionOrder",0,h,"drunkTriggerQuestionId",0,"drink_gate_q2","normalTypes",0,r,"questions",0,n,"slugMap",0,t,"specialQuestions",0,a,"typeImageMap",0,s,"typeLibrary",0,i],48068);let d={q1:{text:"I’m not just a loser, I’m a joker, I’m a washed-up NPC. I’ve never dated in my life. I’m timid, insecure, and my youth has been one long playlist of imaginary romance scenes. Every day I picture myself walking down the street with some girl, going shopping, hanging out, living like a normal person. Reality? I burned my parents’ money, went to a trash school, drifted into a random job, and now I’m a three-no special: no ideals, no goals, no ability. Every time people make fun of losers online, I want to cry, because I am the sewer rat peeking at all the good things on the surface through a crack in the manhole. Every joke feels like another hit to my soul and another shrinkage of my already tiny living space. Please, brothers, leave a little oxygen for clowns like us. I really don’t want to soak my pillowcase with tears in broad daylight.",options:["I’m crying...","What even is this...","That is NOT me!"]},q2:{text:"I’m not good enough. The people around me are all better than me.",options:["True","Sometimes","No"]},q3:{text:"I know very clearly what the real me is like.",options:["Disagree","Neutral","Agree"]},q4:{text:"There’s something I genuinely want in life.",options:["Disagree","Neutral","Agree"]},q5:{text:"I have to keep climbing and becoming more powerful.",options:["Disagree","Neutral","Agree"]},q6:{text:"Other people’s opinions honestly don’t mean that much to me.",options:["Disagree","Neutral","Agree"]},q7:{text:"Your partner hasn’t replied for over five hours and says they had diarrhea. What do you think?",options:["Nobody spends five hours on that. They’re probably hiding something.","I’d swing between trust and suspicion.","Maybe they really do feel awful today."]},q8:{text:"In relationships, I often worry about being abandoned.",options:["Yes","Sometimes","No"]},q9:{text:"I swear to the heavens, I take every relationship seriously!",options:["Not really","Maybe?","Yes, and I mean it"]},q10:{text:"Your partner is respectful, gentle, clean-living, upright, eloquent, observant, knowledgeable, kind, ambitious, elegant, and absurdly gorgeous. What happens next?",options:["Even if they’re amazing, I still wouldn’t fall in too deep.","I’d probably land somewhere between A and C.","I’d treasure them like crazy and might turn into a full-on love-brain."]},q11:{text:"After getting into a relationship, your partner becomes extremely clingy. What’s your honest reaction?",options:["That actually sounds kind of great.","Either way is fine.","I’d rather keep some independent space."]},q12:{text:"In any relationship, I care a lot about personal space.",options:["I prefer dependence and being depended on.","Depends on the situation.","Yes, absolutely."]},q13:{text:"Most people are kind.",options:["Honestly, cruel hearts are more common than hemorrhoids.","Maybe.","Yes. I’d rather believe there are more good people."]},q14:{text:"You’re walking down the street when an impossibly adorable little girl runs up to you and hands you a lollipop. What’s your first thought?",options:["Is this some new scam? I should probably leave.","Completely baffled. Mild head-scratching mode.","Aww, she’s so sweet. She gave me a lollipop!"]},q15:{text:"Exams are coming. School says evening study is mandatory and skipping it costs points, but tonight you already promised your crush you’d play PUBG Mobile together. What do you do?",options:["Skip it. It’s only one night anyway.","I’d try to ask for leave.","Exams are close. Why am I even going out?"]},q16:{text:"I like breaking convention and I hate being boxed in.",options:["Agree","Neutral","Disagree"]},q17:{text:"I usually do things with a goal in mind.",options:["Disagree","Neutral","Agree"]},q18:{text:"One random day I realize life has no damn meaning at all. Humans are just animals driven by urges and hormones: hungry, eat; sleepy, sleep; horny, mate. We’re basically pigs and dogs with extra steps.",options:["That’s exactly it.","Maybe yes, maybe no.","That’s nonsense."]},q19:{text:"I mainly work for progress and achievement, not just to avoid trouble and risk.",options:["Disagree","Neutral","Agree"]},q20:{text:"You’ve been constipated on the toilet for thirty minutes. Which option sounds most like you?",options:["Sit for another thirty. Maybe something will happen.","Slap my own butt and yell, 'Come on, useless butt, do your job!'","Use a laxative and get this over with quickly."]},q21:{text:"I make decisions fairly fast and don’t enjoy hesitating.",options:["Disagree","Neutral","Agree"]},q22:{text:"This question has no prompt. Choose blindly.",options:["After overthinking it, A feels right?","Uh... maybe B?","When in doubt, pick C."]},q23:{text:"When someone says you 'have strong execution,' which thought feels closest to the truth?",options:["I only get insanely efficient at the very last second...","Sometimes, I guess.","Yes. Things are supposed to move forward."]},q24:{text:"When I make plans, ____",options:["life usually outruns them.","sometimes I finish them, sometimes I don’t.","I hate when my plan gets broken."]},q25:{text:"You met a bunch of online friends through Identity V and they invite you to meet offline. What’s your reaction?",options:["Talking big online is one thing. Meeting for real still feels a bit scary.","Sure, why not. If somebody talks, I’ll chat back a little.","I’d dress up and chat enthusiastically. You never know, right?"]},q26:{text:"Your friend brings one of their friends to hang out. What’s your most likely mode?",options:["I instinctively keep a little distance from 'my friend’s friend.'","Depends on them. If we click, we click.","A friend of my friend is basically my friend. Let’s talk!"]},q27:{text:"My relationships come with an electronic fence. If people get too close, the alarm goes off automatically.",options:["Agree","Neutral","Disagree"]},q28:{text:"I crave deep closeness with people I trust, like we’re long-lost relatives reunited.",options:["Agree","Neutral","Disagree"]},q29:{text:"Sometimes you clearly have a negative take on something but choose not to say it. Most of the time, why?",options:["That situation doesn’t happen often.","Probably because of the vibe, the relationship, or basic tact.","I don’t want people to know I’m kind of a dark little creature."]},q30:{text:"I show different versions of myself around different people.",options:["Disagree","Neutral","Agree"]}},u={drink_gate_q1:{text:"What kind of hobby do you usually have?",options:["Eat, sleep, survive","Art stuff","Drinking","Working out"]},drink_gate_q2:{text:"What’s your attitude toward alcohol?",options:["A little is nice. I can’t drink that much.","I pour baijiu into a thermos and drink it like water. Alcohol has my absolute respect."]}},c={CTRL:{cn:"The Handler",intro:"See? Handled you already.",desc:"Congratulations. You rolled one of the rarest personalities in the SBTI universe. CTRL people look like they were born with a task manager installed straight into their nervous system. What ordinary people call 'rules' feels like factory settings to you; what ordinary people call 'planning' looks more like a rough doodle compared with the way your brain arranges reality. Having a CTRL around is like having an emergency Ctrl+S key living next to you. Right before someone’s life starts derailing, CTRL will archive the chaos, restore the correct version, and drag the whole situation back on track with logic too clean to argue with. In a collapsing universe, they are the last reboot button still glowing."},"ATM-er":{cn:"The Walking ATM",intro:"Do I really look that rich to you?",desc:"ATM-er does not necessarily mean throwing cash everywhere. It means always being the one who pays. Paying with time, paying with emotional bandwidth, paying with patience, paying with a night that should have belonged to peace and sleep. Other people insert panic and trouble into you like a card into an old but reliable machine, and what comes out is the receipt that says, 'It’s okay, I’ve got this.' Your life is a grand one-person checkout lane that nobody applauds, powered by a responsibility complex that simply refuses to clock out."},"Dior-s":{cn:"The Cynic Sage",intro:"Just wait for my underdog comeback.",desc:"You are not merely a loser archetype. You are the spiritually misplaced heir of Diogenes himself. Dior-s personalities don’t reject ambition because they are lazy; they reject it because they’ve already seen that the endgame of conventional 'success' is often just a more expensive prison. When other people chase trends and get tossed around by the era, Dior-s is sunbathing in a barrel of their own making, perfectly at peace. Their philosophy is brutally practical: lying down is often more comfortable than standing up, and when it’s mealtime, you eat. Simple. Tested. True."},BOSS:{cn:"The Boss",intro:"Hand me the wheel. I’m driving.",desc:"BOSS is the kind of person who reaches for the steering wheel even when the tank is almost empty and the navigation app is clearly hallucinating. You say 'I’ll drive,' and somehow the car still reaches the destination. Efficiency is not a preference here. It is doctrine. Order is not a hobby. It is oxygen. BOSS personalities don’t merely have leadership aura; they generate the aura itself. Within a few meters, the air gets more serious and more productive. What normal people call self-improvement, they often treat like warm-up stretches before the real work begins."},"THAN-K":{cn:"The Thanker",intro:"I thank the heavens. I thank the earth.",desc:"THAN-K people possess a supernatural ability to turn irritation into gratitude with terrifying speed. Traffic jam? Excellent, now there is more time to listen to this beautiful song and study the anxious faces outside the window. Bad weather? Wonderful, now the universe has offered a new angle from which to appreciate existence. Their softness is real, but so is their power. A THAN-K friend is like carrying around a renewable energy tower that runs on perspective and grace. Even mildew in the corner of a wall can become a Van Gogh sky if they are the one describing it."},"OH-NO":{cn:"The Alarmist",intro:"Oh no. Why did I get this one?!",desc:"To the OH-NO personality, 'oh no' is not panic. It is advanced cognition. When ordinary people see a glass near the edge of a table, OH-NO sees the full cinematic franchise: spilled water, short circuit, fire, building evacuation, financial loss, butterfly effect, apocalypse. Then, with a single sacred 'oh no,' they move the glass to the center of the table and place a coaster under it for good measure. They respect boundaries and risk with almost religious intensity. They are the straight-backed guardians of order in a world that keeps trying to slip on its own banana peel."},GOGO:{cn:"The Go-Goer",intro:"Go go go. Let’s move.",desc:"GOGO people live in an extreme what-you-see-is-what-you-get reality. Their life philosophy is beautifully savage: if I close my eyes, then it’s dark; if I spend all my money, then I clearly have no money left; if I’m standing on the crosswalk, then I am now a pedestrian. Flawless loop. Impossible to debate. While others are still dissecting a problem, GOGO has already turned the chicken and the egg into one decisive over-rice combo and called the issue solved. They do not 'process complexity.' They delete pending tasks."},SEXY:{cn:"The Heartthrob",intro:"You were born to be irresistible.",desc:"When you enter a room, the lighting system seems to identify you as the focal subject and quietly lower the brightness to save electricity. When you smile, the humidity in the room drops because all the water vapor has condensed into heart shapes inside other people’s eyes. SEXY personalities do not always need effortful performance. Their existence itself behaves like a dramatic essay written in expensive perfume. If enough SEXY types gathered in one place, it would not be shocking if time itself slowed down a little just to admire the scene."},"LOVE-R":{cn:"The Lover",intro:"There is so much love in here that reality feels underfunded.",desc:"LOVE-R is the emotional endangered species that somehow survived into the algorithm age. Your inner processor is not binary. It runs in rainbow mode. A single falling leaf does not say 'autumn' to you; it opens a thirteen-act tragedy about fate, sacrifice, renewal, and silent devotion. Your inner world feels like an amusement park that never closes, and somewhere deep inside it is a constant search for the one person who can read the map, understand the rides, and stay beside you until the universe turns its lights off."},MUM:{cn:"The Mom Friend",intro:"Maybe... can I call you mom...?",desc:"MUM energy existed before language, before clocks, before the first star burped itself into the sky. The core color of this personality is gentleness. They notice emotion fast, read atmosphere well, and often know exactly when to stop, when to comfort, and when to tell themselves, 'It’s okay, let it go.' MUM types are natural healers of other people’s sadness. The only tragic detail is that when they cry, the dosage of kindness they prescribe to themselves is often smaller than the dosage they freely hand to everyone else."},FAKE:{cn:"The Masker",intro:"There are no humans left.",desc:"In social situations, FAKE personalities switch masks faster than most people switch keyboards. One second it is heart-to-heart bestie mode, next second the boss walks in and the reliable-professional mask snaps into place with showroom-level polish. You thought you found someone who truly understood you? Maybe you simply met an extraordinarily high-performance imitation life-form. The late-night horror of the FAKE personality is that when every mask finally comes off, what remains underneath may feel alarmingly empty, because the masks were the structure all along."},OJBK:{cn:"The Whatever",intro:"When I say 'anything works,' I mean it.",desc:"OJBK is no longer just a personality. It is a system of governance. While ordinary mortals burn precious brain cells deciding whether to eat rice or noodles for lunch, the OJBK personality glances over the entire human dilemma and delivers an imperial decree: 'Whatever.' This is not indecision. This is scale. They are quietly informing you that your tiny earthly choices do not qualify as meaningful events in the empire. They do not argue because arguing with protozoa about the destiny of the universe is beneath the throne."},MALO:{cn:"The Chaos Monkey",intro:"Life is a dungeon run and I’m just a little monkey in it.",desc:"Friend, you are not 'young at heart.' You simply never completed the full human upgrade. Your spirit still hangs from a tree, thrilled by simple joy and suspicious of civilization. When humanity came down from the branches, learned to stand upright, and started wearing ties to meetings, the MALO ancestor stayed above them, scratched their butt, and made a dismissive little monkey sound. MALO understands something most people forget: civilization is often a boring pay-to-win game. Rules can be broken, ceilings can be climbed, and meeting rooms can absolutely be used for backflips."},"JOKE-R":{cn:"The Jester",intro:"Turns out we are all clowns.",desc:"JOKE-R is less a person and more a clown wearing another clown wearing another joke. Peel back one layer and there is a bit. Peel back another and there is a punchline. Keep opening and eventually you hit the empty center, where only a tiny echo remains saying, 'Ha. Didn’t expect that, huh?' JOKE-Rs are the designated mood crew of every social gathering. With them around, the room does not go cold. The loudest laugh often comes from them too, because sometimes the biggest laugh is simply the most efficient way to cover the sound of a fracture inside."},"WOC!":{cn:"The Whoa Person",intro:"Whoa, how did I get this one?",desc:"WOC! personalities run on two separate operating systems. The surface system exists to produce highly expressive sound effects like 'holy crap,' 'no way,' and 'what?!' The background system stays calm, cool, and deeply unsurprised: yes, that tracks, exactly as expected. WOC! types are usually not interested in unnecessary meddling. They know that explaining logic to an idiot is like trying to plaster a wall with mud: exhausting, degrading, and somehow you still end up dirty. So instead they grip a blade of wise grass and honor the absurd world with one heartfelt, perfectly timed 'WOC!'"},"THIN-K":{cn:"The Thinker",intro:"Deep-thinking session: 100 seconds and counting.",desc:"THIN-K brains are built differently. Your mind seems to run in continuous analysis mode. Information is not simply received; it is interrogated, cross-examined, and logged together with its logic chain, hidden bias profile, and background report on the author’s ideological ancestors. In an age of information overload, you are not easily carried away. You weigh costs and benefits in relationships, guard your mental space fiercely, and when other people think you are spacing out alone, what is actually happening is an internal filing operation of terrifying sophistication."},SHIT:{cn:"The Malcontent",intro:"This world is one giant pile of crap.",desc:"SHIT personalities are walking paradox engines. Mouth: 'This project is garbage.' Hands: quietly open Excel and build a full model plus gantt chart. Mouth: 'These coworkers are all unbearable.' Hands: stay up late cleaning the entire mess after everyone else fumbles it. Mouth: 'The world is crap. Burn it down.' Body: wakes up at seven the next morning and squeezes into a miserable commute to keep the machine running anyway. Do not confuse the profanity with surrender. That alarm sound is actually the trumpet announcing that they are about to save the world again, resentfully and efficiently."},ZZZZ:{cn:"The Snoozer",intro:"I’m not dead. I’m just sleeping.",desc:"A ZZZZ type can ignore ninety-nine unread messages in the group chat with saint-level stillness. But once someone sends 'deadline in thirty minutes' with an @everyone attached, they rise like a mummy cracking open a stone tomb, type a slow 'received,' and then somehow submit a passable result in twenty-nine minutes. This personality does not truly awaken until the highest-authority command appears: the deadline itself. Until that exact moment, nothing moves. Once it hits, the legendary last-second surge arrives and proves a cosmic principle: sometimes the best way to avoid doing something wrong is to do absolutely nothing until panic becomes fuel."},POOR:{cn:"The Specialist",intro:"I’m broke, but I’m focused.",desc:"POOR does not mean your wallet got sentenced. It means your desires have gone through ruthless downsizing. While other people scatter their attention like QR codes all over the sky, you compress yours into a single laser beam. The world of POOR is simple: irrelevant things get muted, important things get drilled hard. Noise, vanity, social performance, random networking? Sorry, no bandwidth. It may look like scarcity from the outside, but in practice it is concentration so intense it starts to resemble mining equipment."},MONK:{cn:"The Monk",intro:"No worldly cravings here.",desc:"While other people scream their love songs inside a KTV room, MONK is at home studying a higher path. This personality has already half-left the mortal world and does not appreciate random visitors disturbing their cultivation. Personal space is not a preference to MONK. It is a barrier field, a sacred mountain, an absolute domain. Enter at your own risk. They do not cling because their worldview assumes everything deserves its own orbit. If planets can love each other while staying millions of miles apart, why should humans insist on breathing directly into one another’s souls?"},IMSB:{cn:"The Self-Roaster",intro:"Wait. Seriously? Am I actually that dumb?",desc:"IMSB personalities contain two immortal warriors locked in endless combat. One is named 'Just do it, go for it!' The other is named 'You idiot, you are going to humiliate yourself.' When IMSB meets someone they like, the first screams for action, courage, and grand romantic heroism. The second immediately drags the whole fantasy into a pit of shame and imagined rejection. Final result: they stare at the person’s back until it disappears from view, then pull out their phone and search 'how to overcome social anxiety.' IMSB is not truly stupid. It just has an inner cinema universe that never stops screening."},SOLO:{cn:"The Loner",intro:"I’m crying. How did I end up as the loner?",desc:"SOLO personalities often keep their self-worth low and their defenses high. Instead of reaching outward, they sometimes step back first and build a long wall around the soul that says, in very bold letters, 'Do not come closer.' Every brick in that wall used to be a wound. SOLO is the hedgehog that hides every soft spot and points its sharpest spines at the world. Those spikes are not only aggression. They are also unsent messages saying, 'Please don’t come near, I’m afraid you’ll get hurt too,' and at the exact same time, 'Please don’t leave.'"},FUCK:{cn:"The Wild One",intro:"What the hell is this personality?",desc:"Somewhere inside human civilization lives a humanoid weed that no herbicide can kill. That is the FUCK personality. In their worldview, polite social rules are frequently meaningless, and their emotional switch is not digital but physical: it flips directly between FUCK YEAH and FUCK OFF. They are not chasing only instant pleasure. They are chasing raw vitality, the feeling of being fully alive while their blood seems to ram through every wall in the body. When everyone else has been tamed into well-behaved domestic birds, FUCK is still the last wolf howl coming from the wilderness."},DEAD:{cn:"The Deadpan",intro:"Am I... even alive?",desc:"The DEAD personality is not simply low-energy. It feels more like someone who already completed every main quest, side quest, hidden quest, deleted the save file, restarted nine hundred and ninety-nine times, and eventually realized the game itself was never all that interesting. They look at the world with the tired calm of a post-desire sage. This is what happens when somebody stops investing faith in every fake source of urgency and no longer sees meaning in most of the noise. Their existence becomes a silent, elegant protest against the entire overclocked modern circus."},IMFW:{cn:"The Fragile One",intro:"Am I really... that useless?",desc:"IMFW is not ordinary weakness. It is a rare and hyper-sensitive personality type with brittle pride, thin safety walls, and a heart that is far more serious than it looks. Because of that, IMFW can locate the strongest Wi-Fi signal in any room, meaning the single person they instinctively trust the most. Walking into an IMFW life is like entering a high-end orchid greenhouse: the temperature, humidity, and daily verbal photosynthesis of 'I care about you' all matter. Give them one piece of candy and they may answer with a pair of shining eyes full of trust. Maybe you are not useless at all. Maybe you are simply too undefended."},HHHH:{cn:"The Goofball",intro:"Hahahahahahaha.",desc:"Congratulations. Your mental wiring is so novel that the standard personality library has collapsed in protest. HHHH is only assigned when your highest normal-type match drops below sixty percent, meaning the system itself has more or less thrown up its hands and said, 'I genuinely have no proper drawer for this person.' What qualities define HHHH? Hahahahahahaha. Sorry, that really is most of the official documentation. You can still inspect the fifteen dimensions for an extremely unofficial reading, but the honest truth is that your brain arrived through a side door the original framework forgot to build for."},DRUNK:{cn:"The Drunkard",intro:"Liquor burns the throat. Sobriety was never an option.",desc:"Why are you walking like the ground is moving? Why are your emotions permanently overclocked? Why does the world come with built-in double vision? Because what runs through your veins is not blood but premium baijiu. DRUNK is the hidden route where ethanol takes over the operating system and skips the ordinary trial altogether. Perhaps you have already reached the point of pouring liquor into a thermos and drinking it like water. Alcohol turns you into a banquet philosopher, a nightclub poet, a flaming sun at the center of the table. Then ten in the morning arrives, your head splits like a walnut, food crumbs cling to the corner of your mouth, and your soul retreats into a dark little corner. At last you understand that last night’s heroic orator has officially become a drunkard."}},m=n.map(e=>({...e,options:e.options.map(e=>({...e}))})),p=a.map(e=>({...e,options:e.options.map(e=>({...e}))})),y=m.map(e=>{let t=d[e.id];return{...e,text:t.text,options:e.options.map((e,o)=>({...e,label:t.options[o]??e.label}))}}),g=p.map(e=>{let t=u[e.id];return{...e,text:t.text,options:e.options.map((e,o)=>({...e,label:t.options[o]??e.label}))}}),f={zh:i,en:Object.fromEntries(Object.keys(i).map(e=>[e,{code:e,...c[e]}]))},b={zh:o,en:{S1:{name:"S1 Self-worth & Confidence",model:"Self Model"},S2:{name:"S2 Self-clarity",model:"Self Model"},S3:{name:"S3 Core Values",model:"Self Model"},E1:{name:"E1 Attachment Security",model:"Emotion Model"},E2:{name:"E2 Emotional Investment",model:"Emotion Model"},E3:{name:"E3 Boundaries & Dependence",model:"Emotion Model"},A1:{name:"A1 Worldview Bias",model:"Attitude Model"},A2:{name:"A2 Rules & Flexibility",model:"Attitude Model"},A3:{name:"A3 Sense of Meaning",model:"Attitude Model"},Ac1:{name:"Ac1 Motivational Direction",model:"Action Model"},Ac2:{name:"Ac2 Decision Style",model:"Action Model"},Ac3:{name:"Ac3 Execution Pattern",model:"Action Model"},So1:{name:"So1 Social Initiative",model:"Social Model"},So2:{name:"So2 Interpersonal Boundaries",model:"Social Model"},So3:{name:"So3 Expression & Authenticity",model:"Social Model"}}},w={zh:l,en:{S1:{L:"You roast yourself harder than other people ever could, and compliments immediately trigger authenticity checks.",M:"Your confidence rises and falls with the weather. Tailwind makes you soar; headwind makes you shrink first.",H:"You have a fairly stable sense of yourself and random strangers are not enough to scatter it."},S2:{L:"There is a lot of static on your inner channel. 'Who am I?' tends to stay on loop.",M:"You usually recognize yourself, though emotions occasionally hijack the login.",H:"You know your temper, your wants, and your bottom lines pretty well."},S3:{L:"Comfort and safety matter more. Life does not need to run in sprint mode every day.",M:"You want growth, but you also want to lie down for a while. Your values hold frequent internal meetings.",H:"Goals, growth, or a core belief often pull you forward with real force."},E1:{L:"Your relationship alarm system is highly sensitive. Even being left on read can spin into a full disaster movie.",M:"Half trust, half testing. Emotional tug-of-war is common inside you.",H:"You are more willing to trust the relationship itself and less likely to panic over every tiny disturbance."},E2:{L:"You invest emotionally with restraint. The door is not locked, but security is strict.",M:"You do invest, just with a backup plan. Not a full all-in.",H:"Once you commit, you tend to be serious and generous with emotion and attention."},E3:{L:"You can be clingy and easy to cling to. Warmth in relationships matters a lot.",M:"You want both closeness and independence. Dependence is adjustable.",H:"Space matters. No matter how much you care, you still need a zone that stays yours."},A1:{L:"You view the world through a defensive filter: suspicion first, closeness second.",M:"You are neither naive nor fully conspiratorial. Watching from a distance is your default.",H:"You are more willing to trust human goodness and less eager to declare the world hopeless."},A2:{L:"If a rule can be bent, you will consider it. Comfort and freedom often rank first.",M:"You follow rules when it makes sense and flex when it doesn’t.",H:"Your sense of order is strong. If there is a proper process, you would rather not freestyle chaos."},A3:{L:"Meaning runs low. Many things feel like going through motions.",M:"Sometimes you have a purpose, sometimes you want to rot quietly. Your worldview is half booted.",H:"You move with more direction and usually know roughly where you are trying to go."},Ac1:{L:"Risk control boots up before ambition does.",M:"Sometimes you want to win, sometimes you just want less hassle. Motivation is mixed.",H:"Results, growth, and momentum light you up more easily."},Ac2:{L:"You tend to spin a few extra circles before deciding. Internal meetings often run overtime.",M:"You think, but not to the point of total system freeze. Normal hesitation.",H:"You decide fast and dislike revisiting the same choice over and over."},Ac3:{L:"Your execution has a deep emotional bond with the deadline. The later it gets, the more awakened you become.",M:"You can do it, but timing matters. Sometimes steady, sometimes floppy.",H:"You have a strong urge to push things through. If something stays unfinished, it feels like a thorn in your brain."},So1:{L:"Your social engine warms up slowly. Initiating contact usually takes effort to gather.",M:"If people come to you, you respond. If they don’t, you do not force it. Moderate elasticity.",H:"You are more willing to open the scene yourself and are not too afraid of standing out in a crowd."},So2:{L:"You prefer closeness and merging. Once people are in, they get pulled into the inner ring quickly.",M:"You want closeness and distance in adjustable proportions depending on the person.",H:"Your boundaries run strong. If someone gets too close, your body instinctively steps back first."},So3:{L:"Your expression is direct. If it is in your heart, you usually do not enjoy wrapping it in loops.",M:"You read the room before speaking. Authenticity and tact both get a seat at the table.",H:"You switch versions of yourself smoothly across contexts, and your 'realness' gets distributed in layers."}}},v=[{title:"自我模型",description:"看你对自己的评价是否稳定，认不认识自己，以及内心到底有没有特别要紧的东西。"},{title:"情感模型",description:"看你在关系里容易焦虑还是安心，投入到什么程度，以及是否需要独立空间。"},{title:"态度模型",description:"看你怎么看世界、规则和人生意义，是谨慎守序还是灵活冲动。"},{title:"行动驱力模型",description:"看你做事更偏进攻还是规避，做决定果不果断，计划能不能落下来。"},{title:"社交模型",description:"看你会不会主动靠近人、边界感强不强，以及在不同关系里有多真实。"}],M=[{title:"Self Model",description:"Looks at how stable your self-evaluation is, whether you know yourself clearly, and whether there is something inside you that truly matters."},{title:"Emotion Model",description:"Looks at whether you feel anxious or secure in relationships, how deeply you invest, and how much independence you need."},{title:"Attitude Model",description:"Looks at how you see the world, rules, and meaning: cautious and orderly, or flexible and impulsive."},{title:"Action Model",description:"Looks at whether you move toward growth or away from risk, how decisive you are, and whether your plans actually land."},{title:"Social Model",description:"Looks at whether you approach people actively, how strong your boundaries are, and how authentic you stay across relationships."}],H=Object.fromEntries(r.map(e=>[e.code,e.pattern])),k=new Set(["HHHH","DRUNK"]);function L(e){return Object.keys(e).map(o=>({...e[o],slug:t[o],image:s[o],pattern:H[o],special:k.has(o),code:o}))}let O={zh:L(f.zh),en:L(f.en)},I={zh:Object.fromEntries(O.zh.map(e=>[e.code,e])),en:Object.fromEntries(O.en.map(e=>[e.code,e]))},S={zh:Object.fromEntries(O.zh.map(e=>[e.slug,e])),en:Object.fromEntries(O.en.map(e=>[e.slug,e]))},T={zh:v.map(e=>({...e,dimensions:h.filter(t=>b.zh[t].model===e.title)})),en:M.map(e=>({...e,dimensions:h.filter(t=>b.en[t].model===e.title)}))},A=b.zh,x=O.zh,E=I.zh;S.zh,T.zh,w.zh,Object.fromEntries(x.filter(e=>e.pattern).map(e=>{let t=e.pattern.split("-").flatMap(e=>e.split(""));return[e.code,Object.fromEntries(h.map((e,o)=>[e,t[o]]))]})),m.length,p.length;let q=m.length+1;e.s(["dimensionMeta",0,A,"getDimExplanations",0,function(e="zh"){return w[e]},"getDimensionMeta",0,function(e="zh"){return b[e]},"getQuestions",0,function(e="zh"){return"en"===e?y:m},"getSpecialQuestions",0,function(e="zh"){return"en"===e?g:p},"getTypeByCodeMap",0,function(e="zh"){return I[e]},"questions",0,m,"requiredQuestionCount",0,q,"typeByCode",0,E],84807);var K=e.i(18071);e.s(["getHomeHref",0,function(e="zh"){return(0,K.localizePath)(e,"/")},"getRankingsHref",0,function(e="zh"){return(0,K.localizePath)(e,"/rankings")},"getResultHref",0,function(e,t="zh"){return(0,K.localizePath)(t,`/result/${e}`)},"getTestHref",0,function(e="zh"){return(0,K.localizePath)(e,"/test")}],96382)}]);